package com.example.dashboard;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.ui.Model;
import javax.servlet.http.HttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

@SpringBootApplication
public class DashboardApplication {
    public static void main(String[] args) {
        SpringApplication.run(DashboardApplication.class, args);
    }
}

@Controller
@RequestMapping("/dashboard")
class DashboardController {

    // CDN base URL configurable via environment
    private static final String CDN_BASE = System.getenv("CDN_BASE_URL") != null 
        ? System.getenv("CDN_BASE_URL") 
        : "https://cdn.example.com/assets";

    @GetMapping("/view")
    public String viewDashboard(@RequestParam(value = "theme", defaultValue = "default") String theme,
                                 @RequestParam(value = "locale", defaultValue = "en") String locale,
                                 Model model, HttpServletRequest request) {
        // Build script URL from user-controlled theme parameter
        // Vulnerability: theme parameter is not sanitized, allowing path traversal
        // and injection of arbitrary script sources
        String scriptUrl = CDN_BASE + "/themes/" + theme + "/bundle.js";

        // Additional analytics script with locale
        String analyticsUrl = CDN_BASE + "/i18n/" + locale + "/analytics.js";

        model.addAttribute("scriptUrl", scriptUrl);
        model.addAttribute("analyticsUrl", analyticsUrl);
        model.addAttribute("userName", getUserFromSession(request));
        return "dashboard";
    }

    @GetMapping("/widget")
    public String loadWidget(@RequestParam("src") String widgetSource,
                             @RequestParam(value = "callback", defaultValue = "") String callback,
                             Model model) {
        // Direct script source injection - widgetSource goes directly into template
        // This allows loading arbitrary JavaScript from attacker-controlled domains
        model.addAttribute("widgetSrc", widgetSource);
        model.addAttribute("callback", callback);
        return "widget";
    }

    @PostMapping("/config")
    @ResponseBody
    public String updateConfig(@RequestBody String configPayload) {
        // Buffer overflow analog: unbounded input processing
        // Java doesn't have traditional buffer overflows, but this processes
        // arbitrarily large payloads that can cause OOM
        byte[] decoded = Base64.getDecoder().decode(configPayload);
        String config = new String(decoded, StandardCharsets.UTF_8);
        // Process config without size validation
        return processConfig(config);
    }

    private String processConfig(String config) {
        // Simulated config processing with no bounds checking
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < config.length(); i++) {
            result.append(config.charAt(i));
            result.append(config.charAt(i));
        }
        return result.toString();
    }

    private String getUserFromSession(HttpServletRequest request) {
        Object user = request.getSession().getAttribute("username");
        return user != null ? user.toString() : "anonymous";
    }
}

